import hashlib
from lfx.custom.custom_component.component import Component
from lfx.io import Output, StrInput, SecretStrInput, HandleInput
from lfx.schema.message import Message
from lfx.template.field.base import Input


class OpenSearchDirectIngest(Component):
    display_name = "OpenSearch Direct Ingest"
    description = "Embed texts via connected Embedding Model and bulk insert into OpenSearch. Replaces existing docs with same source_url."

    inputs = [
        Input(name="chunks", display_name="Chunks", input_types=["DataFrame"]),
        HandleInput(
            name="embedding",
            display_name="Embedding Model",
            input_types=["Embeddings"],
            required=True,
        ),
        MessageTextInput(name="opensearch_url", display_name="OpenSearch URL", value="http://opensearch:9200"),
        MessageTextInput(name="index_name", display_name="Index Name", value="langflow"),
        StrInput(name="username", display_name="Username", value="admin"),
        SecretStrInput(name="password", display_name="Password"),
    ]

    outputs = [
        Output(display_name="Result", name="result", method="ingest"),
    ]

    def ingest(self) -> Message:
        from opensearchpy import OpenSearch, helpers

        df = self.chunks
        text_col = "text" if "text" in df.columns else df.columns[0]
        rows = df[df[text_col].astype(str).str.strip() != ""].to_dict("records")

        if not rows:
            return Message(text="No documents to ingest.")

        client = OpenSearch(
            hosts=[self.opensearch_url],
            http_auth=(self.username, self.password),
            use_ssl=False,
            verify_certs=False,
        )

        # --- 同一source_urlの既存データを削除(丸ごと更新) ---
        deleted_count = 0
        if client.indices.exists(index=self.index_name):
            source_urls = list({row.get("source_url") for row in rows if row.get("source_url")})
            if source_urls:
                del_res = client.delete_by_query(
                    index=self.index_name,
                    body={"query": {"terms": {"source_url.keyword": source_urls}}},
                    conflicts="proceed",
                )
                deleted_count = del_res.get("deleted", 0)

        texts = [row[text_col] for row in rows]

        # --- Embedding ---
        if hasattr(self.embedding, "embed_query"):
            vectors = [self.embedding.embed_query(t) for t in texts]
        else:
            vectors = self.embedding.embed_documents(texts)

        if len(vectors) != len(texts):
            return Message(text=f"MISMATCH: texts={len(texts)}, vectors={len(vectors)}")

        dim = len(vectors[0])

        # --- Index存在しなければ作成 ---
        if not client.indices.exists(index=self.index_name):
            mapping = {
                "settings": {"index": {"knn": True}},
                "mappings": {
                    "properties": {
                        "text": {"type": "text"},
                        "chunk_embedding": {
                            "type": "knn_vector",
                            "dimension": dim,
                        },
                    }
                },
            }
            client.indices.create(index=self.index_name, body=mapping)

        # --- Bulk insert ---
        actions = [
            {
                "_index": self.index_name,
                "_id": hashlib.md5(f"{row.get('source_url','')}-{i}".encode("utf-8")).hexdigest(),
                "_source": {
                    "text": row[text_col],
                    "chunk_embedding": vec,
                    **{k: v for k, v in row.items() if k != text_col},
                },
            }
            for i, (row, vec) in enumerate(zip(rows, vectors, strict=False))
        ]
        success, errors = helpers.bulk(client, actions, raise_on_error=False)

        return Message(
            text=f"Deleted old: {deleted_count}, Indexed: {success}, Errors: {len(errors) if errors else 0}"
        )
